mapper.select:
SELECT COUNT(*)
FROM sr_dag_edge ed
JOIN sr_dag_node_instance ni
  ON ni.dag_instance_id = #{dagInstanceId}
 AND ni.node_id = ed.from_node_id
WHERE ed.dag_definition_version_id = #{dagDefinitionVersionId}
  AND ed.to_node_id = #{toNodeId}
  AND ni.status != 50

SELECT DISTINCT to_node_id AS node_id
FROM sr_dag_edge
WHERE dag_definition_version_id = #{dagDefinitionVersionId}
  AND from_node_id = #{fromNodeId}

SELECT DISTINCT from_node_id AS node_id
FROM sr_dag_edge
WHERE dag_definition_version_id = #{dagDefinitionVersionId}
  AND to_node_id = #{toNodeId}

SELECT n.node_id
FROM (
    SELECT node_id
    FROM sr_dag_definition_version dv, JSONB_ARRAY_ELEMENTS(dv.definition_snapshot -> 'nodes') AS n(node_id)
    WHERE dv.id = #{dagDefinitionVersionId}
) n
LEFT JOIN sr_dag_edge e
  ON e.dag_definition_version_id = #{dagDefinitionVersionId}
 AND e.to_node_id = n.node_id ->> 'id'
WHERE e.id IS NULL
